#include <bits/stdc++.h>
using namespace std;

int main(){
    int T;
    scanf("%d",&T);
    while(T--){
        int n;
        scanf("%d",&n);
        vector<int> p(n+1);
        for(int i=1;i<=n;i++) scanf("%d",&p[i]);

        vector<pair<int,int>> edges(n-1);
        vector<vector<pair<int,int>>> adj(n+1);
        for(int i=0;i<n-1;i++){
            int u,v;
            scanf("%d%d",&u,&v);
            edges[i]={u,v};
            adj[u].push_back({v,i});
            adj[v].push_back({u,i});
        }

        // BFS from root=1 to get parent/depth
        vector<int> par(n+1,0), depth(n+1,0);
        vector<vector<int>> children(n+1);
        {
            vector<bool> vis(n+1,false);
            queue<int> q;
            q.push(1); vis[1]=true;
            while(!q.empty()){
                int u=q.front();q.pop();
                for(auto [v,ei]:adj[u]) if(!vis[v]){
                    vis[v]=true; par[v]=u; depth[v]=depth[u]+1;
                    children[u].push_back(v);
                    q.push(v);
                }
            }
        }

        // LCA for path queries
        // For checking if v is on path from u to target: 
        // ancestor check using in/out times
        vector<int> tin(n+1), tout(n+1);
        int timer=0;
        // iterative DFS for euler tour
        {
            stack<pair<int,bool>> st;
            st.push({1,false});
            while(!st.empty()){
                auto [u,back]=st.top(); st.pop();
                if(back){tout[u]=timer++;continue;}
                tin[u]=timer++;
                st.push({u,true});
                for(int i=children[u].size()-1;i>=0;i--)
                    st.push({children[u][i],false});
            }
        }
        auto isAnc=[&](int u,int v)->bool{return tin[u]<=tin[v]&&tout[v]<=tout[u];};
        // LCA
        vector<vector<int>> up(20,vector<int>(n+1,0));
        for(int i=1;i<=n;i++) up[0][i]=par[i];
        for(int k=1;k<20;k++) for(int i=1;i<=n;i++) up[k][i]=up[k-1][up[k-1][i]];
        auto lca=[&](int u,int v)->int{
            if(isAnc(u,v))return u; if(isAnc(v,u))return v;
            for(int k=19;k>=0;k--) if(up[k][u]&&!isAnc(up[k][u],v)) u=up[k][u];
            return up[0][u];
        };
        auto dist=[&](int u,int v)->int{int l=lca(u,v);return depth[u]+depth[v]-2*depth[l];};
        auto onPath=[&](int u,int v,int x)->bool{return dist(u,x)+dist(x,v)==dist(u,v);};

        vector<vector<int>> results;
        for(int iter=0;iter<2*n;iter++){
            bool done=true;
            for(int i=1;i<=n;i++) if(p[i]!=i){done=false;break;}
            if(done) break;
            // For each edge, compute priority
            vector<tuple<int,int,int>> scored; // (priority, random_tiebreak, edge_index)
            for(int i=0;i<n-1;i++){
                auto [u,v]=edges[i];
                int pu=p[u], pv=p[v];
                // Does pu need to cross edge (u,v) toward v to reach target pu?
                bool u_needs = (pu!=u) && onPath(u,pu,v);
                bool v_needs = (pv!=v) && onPath(v,pv,u);
                int pri=0;
                if(u_needs && v_needs) pri=3;
                else if(u_needs || v_needs) pri=2;
                else {
                    // Check if swap gives net benefit
                    int before = dist(u,pu)+dist(v,pv);
                    int after = dist(u,pv)+dist(v,pu);
                    if(after < before) pri=1;
                }
                if(pri>0) scored.push_back({pri,rand(),i});
            }
            sort(scored.begin(),scored.end(),[](auto&a,auto&b){return get<0>(a)>get<0>(b);});

            vector<bool> used(n+1,false);
            vector<int> matching;
            for(auto [pri,rnd,ei]:scored){
                auto [u,v]=edges[ei];
                if(!used[u]&&!used[v]){
                    used[u]=used[v]=true;
                    matching.push_back(ei);
                    swap(p[u],p[v]);
                }
            }
            if(matching.empty()){
                for(int i=0;i<n-1;i++){
                    auto [u,v]=edges[i];
                    if(p[u]!=u||p[v]!=v){matching.push_back(i);swap(p[u],p[v]);break;}
                }
            }
            if(!matching.empty()) results.push_back(matching);
        }
        printf("%d\n",(int)results.size());
        for(auto &m:results){
            printf("%d",(int)m.size());
            for(int ei:m) printf(" %d",ei+1);
            printf("\n");
        }
    }
}
